```cpp
#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

typedef long long ll;

// 树状数组
struct BIT {
    int n;
    vector<int> tree;
    BIT(int n): n(n), tree(n + 1, 0) {}
    void update(int i, int val) {
        for (; i <= n; i += i & -i) {
            tree[i] += val;
        }
    }
    int query(int i) {
        int res = 0;
        for (; i > 0; i -= i & -i) {
            res += tree[i];
        }
        return res;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;
    vector<int> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    if (k >= 3) {
        cout << 0 << "\n";
    } else if (k == 1) {
        // 逆序对数
        BIT bit(n);
        ll inv = 0;
        for (int i = 0; i < n; i++) {
            inv += i - bit.query(a[i]);
            bit.update(a[i], 1);
        }
        cout << inv << "\n";
    } else if (k == 2) {
        // 奇数位置集合
        vector<int> posOdd;
        for (int i = 0; i < n; i++) {
            if (a[i] & 1) {
                posOdd.push_back(i + 1);
            }
        }
        ll ans = 0;
        int m = posOdd.size();
        for (int i = 0; i < m; i++) {
            int target = 2 * i + 1;
            ans += abs(posOdd[i] - target);
        }
        cout << ans << "\n";
    }

    return 0;
}
